import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../App';

const CartScreen: React.FC = () => {
  const navigate = useNavigate();
  const { cart, removeFromCart, updateQuantity, clearCart, cartTotal, promoDiscount, applyPromoCode, serviceType, setServiceType, activePromoCode } = useCart();
  const [coupon, setCoupon] = useState('');
  const [isApplying, setIsApplying] = useState(false);

  const deliveryFee = serviceType === 'pickup' ? 0 : 3000;
  const finalTotal = Math.max(0, cartTotal + deliveryFee - promoDiscount);

  const handleApplyCoupon = async () => {
    if (!coupon.trim()) return;
    setIsApplying(true);
    const success = await applyPromoCode(coupon.trim());
    setIsApplying(false);
    if (!success) {
      alert('⚠️ Cupón inválido. Recuerda que los cupones de referido comienzan por POT-');
    } else {
      setCoupon('');
    }
