  return (
    <div className="flex flex-col h-screen bg-background-light">
      <div className="flex items-center justify-between p-4 bg-background-light sticky top-0 z-10 shrink-0">
        <button onClick={() => navigate(-1)} className="flex items-center justify-center size-10 rounded-full hover:bg-black/5 transition-colors">
