        <div className="flex flex-col gap-4 mt-2">

          {/* Service Type Toggle */}
          <div className="bg-white p-1 rounded-xl shadow-sm border border-gray-100 flex relative">
            <button 
                onClick={() => setServiceType('delivery')}
