            >
                <span className="material-symbols-outlined text-[18px]">moped</span>
                Domicilio
            </button>
            <button 
                onClick={() => setServiceType('pickup')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-bold transition-all z-10 ${serviceType === 'pickup' ? 'text-black bg-primary shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
            >
                <span className="material-symbols-outlined text-[18px]">storefront</span>
                Recoger
            </button>
