          {cart.map(item => (
            <div key={item.id} className="flex gap-4 p-4 bg-white rounded-xl shadow-sm border border-black/5 items-center">
              <div className="bg-center bg-no-repeat bg-cover rounded-lg size-[80px] shrink-0" style={{backgroundImage: `url('${item.image}')`}}></div>
              <div className="flex flex-1 flex-col justify-center min-w-0">
                <div className="flex justify-between items-start">
                  <p className="text-gray-900 text-base font-bold truncate pr-2">{item.name}</p>
                  <button onClick={() => removeFromCart(item.id)} className="text-gray-400 hover:text-red-500 transition-colors shrink-0">
                    <span className="material-symbols-outlined" style={{fontSize: '20px'}}>delete</span>
                  </button>
                </div>
                <div className="flex items-center justify-between mt-1">
                  <p className="text-gray-900 text-base font-bold">${item.price.toLocaleString()}</p>
                  <div className="flex items-center gap-2 bg-background-light rounded-full p-1">
