              <div className="flex justify-between items-center">
                <p className="text-[#8a8060] text-sm">Servicio ({serviceType === 'delivery' ? 'Domicilio' : 'Recoger'})</p>
                <p className="text-gray-900 text-base font-medium">{serviceType === 'pickup' ? 'Gratis' : `$${deliveryFee.toLocaleString()}`}</p>
              </div>
              {promoDiscount > 0 && (
                <div className="flex justify-between items-center text-green-600 font-bold">
                    <p className="text-sm">Descuento</p>
                    <p className="text-base">-${promoDiscount.toLocaleString()}</p>
                </div>
              )}
              <div className="my-2 h-px bg-gray-200 w-full"></div>
              <div className="flex justify-between items-center">
                <p className="text-gray-900 text-lg font-bold">Total</p>
                <p className="text-gray-900 text-xl font-extrabold">${finalTotal.toLocaleString()}</p>
              </div>
            </div>
          </div>
        </div>
        )}
      </div>

      {cart.length > 0 && (
      <div className="fixed bottom-0 left-0 w-full p-4 bg-background-light/95 backdrop-blur-md border-t border-black/5 z-20 max-w-md mx-auto">
