import React, { useMemo, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useOrders, useProducts } from '../App';
import { updateSupabaseConfig, isSupabaseConfigured, getCurrentConfig } from '../supabaseClient';
import { BRAND_CONFIG } from '../constants';

// Fix: Completed the AdminDashboardScreen component and added default export
const AdminDashboardScreen: React.FC = () => {
  const navigate = useNavigate();
  const { orders, clearOrders, loading: ordersLoading } = useOrders();
  const { products } = useProducts();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [pin, setPin] = useState('');
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showQRModal, setShowQRModal] = useState(false);

  // Config State
  const currentConfig = getCurrentConfig();
  const [showConfig, setShowConfig] = useState(false);
  const [sbUrl, setSbUrl] = useState(currentConfig.url);
  const [sbKey, setSbKey] = useState(currentConfig.key);
  const [isConfigured, setIsConfigured] = useState(false);

  // Public URL for QR (saved in localStorage)
  // Limpiamos la URL para que apunte al inicio (home)
  const defaultAppUrl = window.location.origin + window.location.pathname;
  const [publicUrl, setPublicUrl] = useState(localStorage.getItem('potato_public_url') || defaultAppUrl);

  const [newPin, setNewPin] = useState('');

  // QR Logic - Genera el QR basado en la URL pública configurada
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(publicUrl)}&color=000000&bgcolor=FFFFFF&margin=2`;

  useEffect(() => {
      setIsConfigured(isSupabaseConfigured());
  }, []);

  // Analytics Logic
  const analytics = useMemo(() => {
    const productCounts: { [key: string]: number } = {};
    orders.forEach(order => {
        if (Array.isArray(order.items)) {
            order.items.forEach(item => {
                const pId = item.productId || item.id;
                productCounts[pId] = (productCounts[pId] || 0) + item.quantity;
            });
        }
    });

    const topProducts = Object.entries(productCounts)
        .map(([id, count]) => {
            const product = products.find(p => p.id === id);
            return product ? { ...product, count } : null;
        })
        .filter(p => p !== null)
        .sort((a, b) => b!.count - a!.count)
        .slice(0, 3);

    const customerStats: { [key: string]: { name: string, visits: number, spent: number } } = {};

    orders.forEach(order => {
        const phone = order.customerPhone || 'Unknown';
        if (!customerStats[phone]) {
            customerStats[phone] = { name: order.customerName, visits: 0, spent: 0 };
        }
        customerStats[phone].visits += 1;
        customerStats[phone].spent += order.total;
    });

    const loyalCustomers = Object.values(customerStats)
        .sort((a, b) => b.visits - a.visits)
        .slice(0, 5);

    const totalSales = orders.reduce((acc, order) => acc + order.total, 0);
    const totalOrders = orders.length;

    return { topProducts, loyalCustomers, totalSales, totalOrders };
  }, [orders, products]);

  const handleLogin = (val: string) => {
     const storedPin = localStorage.getItem('potato_admin_pin') || '2024';
     if (val === storedPin) {
         setIsAuthenticated(true);
     } else {
         alert('PIN Incorrecto');
         setPin('');
     }
  };

  const handleSavePublicUrl = () => {
    localStorage.setItem('potato_public_url', publicUrl);
    alert('¡URL Pública guardada! El código QR ahora apunta a esta dirección.');
  };

  const handleChangePin = () => {
      if (newPin.length < 4) {
          alert('El PIN debe tener al menos 4 caracteres.');
          return;
      }
      localStorage.setItem('potato_admin_pin', newPin);
      alert('¡PIN actualizado!');
      setNewPin('');
  };

  const handleDeleteHistory = () => {
    clearOrders();
    setShowDeleteModal(false);
  };

  const handleSaveConfig = () => {
      if(!sbUrl || !sbKey) {
          alert("Ingresa URL y Key");
          return;
      }
      updateSupabaseConfig(sbUrl, sbKey);
  };

  const getProductNames = (items: any[]) => {
      if (!Array.isArray(items)) return ['-'];
      return items.map(item => {
          const product = products.find(p => p.id === (item.productId || item.id));
          return product ? `${item.quantity}x ${product.name}` : `${item.quantity}x ${item.name || 'Prod'}`;
      });
  };

  if (!isAuthenticated) {
      return (
          <div className="flex flex-col items-center justify-center min-h-screen bg-background-dark p-6 text-white">
              <span className="material-symbols-outlined text-6xl text-primary mb-4">lock</span>
              <h1 className="text-2xl font-bold mb-2">Acceso Privado</h1>
              <p className="text-gray-400 mb-8 text-center">Dashboard de Administrador</p>

              <div className="w-full max-w-xs">
                  <input 
                    type="password" 
                    value={pin}
                    onChange={(e) => setPin(e.target.value)}
                    placeholder="PIN de acceso"
                    className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-center text-xl tracking-widest mb-4 focus:ring-primary focus:border-primary placeholder:text-gray-500"
                    maxLength={10}
                  />
                  <button 
                    onClick={() => handleLogin(pin)}
                    className="w-full bg-primary text-background-dark font-bold py-4 rounded-xl hover:bg-yellow-400"
                  >
                      Entrar
                  </button>
                  <button onClick={() => navigate('/')} className="w-full mt-4 text-gray-400 text-sm">
                      Volver a la Tienda
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden shadow-2xl bg-gray-50">
      {/* Header */}
      <header className="flex items-center p-4 pt-6 pb-4 justify-between sticky top-0 z-20 bg-white shadow-sm">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full overflow-hidden border border-gray-200">
            <img src={BRAND_CONFIG.LOGO_URL} alt="Logo" className="h-full w-full object-cover p-1" />
          </div>
          <div>
            <h2 className="text-[#181611] text-lg font-bold leading-tight">Admin Dashboard</h2>
            <div className="flex items-center gap-1">
                <div className={`w-2 h-2 rounded-full ${isConfigured ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                <p className="text-xs font-medium text-gray-500">Online</p>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={() => setShowConfig(!showConfig)} className={`flex items-center justify-center h-9 w-9 rounded-full ${showConfig ? 'bg-primary text-black' : 'bg-gray-100 text-gray-600'}`}>
                <span className="material-symbols-outlined text-lg">settings</span>
            </button>
            <button onClick={() => setIsAuthenticated(false)} className="text-sm font-bold text-gray-400">Salir</button>
        </div>
      </header>

      {/* Config Panel */}
      {showConfig && (
        <div className="bg-white border-b border-gray-200 p-4 animate-[slideDown_0.3s_ease-out]">
            <h3 className="font-extrabold text-[#181611] mb-4 text-xs uppercase tracking-widest">Ajustes Globales</h3>

            <div className="space-y-4 mb-6">
                <div>
                    <label className="text-xs font-bold text-gray-600 block mb-1">Tu URL Pública (Para el QR)</label>
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={publicUrl}
                            onChange={(e) => setPublicUrl(e.target.value)}
                            placeholder="https://mi-tienda.com"
                            className="flex-1 text-sm rounded-lg border-gray-200 focus:border-primary"
                        />
                        <button onClick={handleSavePublicUrl} className="bg-black text-white px-3 py-1 rounded-lg text-[10px] font-bold">Guardar URL</button>
                    </div>
                </div>

                <div className="border-t border-gray-100 pt-4">
                    <label className="text-xs font-bold text-gray-600 block mb-1">Cambiar PIN Admin</label>
                    <div className="flex gap-2">
                        <input 
                            type="password" 
                            value={newPin}
                            onChange={(e) => setNewPin(e.target.value)}
                            className="flex-1 text-sm rounded-lg border-gray-200 focus:border-primary"
                        />
                        <button onClick={handleChangePin} className="bg-black text-white px-3 py-1 rounded-lg text-[10px] font-bold">Cambiar</button>
                    </div>
                </div>

                <div className="border-t border-gray-100 pt-4">
                  <label className="text-xs font-bold text-gray-600 block mb-1">Configuración Supabase</label>
                  <div className="space-y-2">
                    <input 
                      type="text" 
                      value={sbUrl}
                      onChange={(e) => setSbUrl(e.target.value)}
                      placeholder="Supabase URL"
                      className="w-full text-sm rounded-lg border-gray-200 focus:border-primary"
                    />
                    <input 
                      type="password" 
                      value={sbKey}
                      onChange={(e) => setSbKey(e.target.value)}
                      placeholder="Supabase Anon Key"
                      className="w-full text-sm rounded-lg border-gray-200 focus:border-primary"
                    />
                    <button onClick={handleSaveConfig} className="w-full bg-black text-white py-2 rounded-lg text-xs font-bold">Actualizar BD</button>
                  </div>
                </div>

                <div className="border-t border-gray-100 pt-4">
                    <button onClick={() => setShowDeleteModal(true)} className="w-full bg-red-50 text-red-600 py-2 rounded-lg text-xs font-bold hover:bg-red-100 transition-colors">
                        Borrar Historial
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Main Content Area */}
      <main className="flex-1 p-4 space-y-6">
