          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full overflow-hidden border border-gray-200">
            <img src={BRAND_CONFIG.LOGO_URL} alt="Logo" className="h-full w-full object-cover p-1" />
          </div>
          <div>
            <h2 className="text-[#181611] text-lg font-bold leading-tight">Admin Dashboard</h2>
            <div className="flex items-center gap-1">
                <div className={`w-2 h-2 rounded-full ${isConfigured ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                <p className="text-xs font-medium text-gray-500">Online</p>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={() => setShowConfig(!showConfig)} className={`flex items-center justify-center h-9 w-9 rounded-full ${showConfig ? 'bg-primary text-black' : 'bg-gray-100 text-gray-600'}`}>
                <span className="material-symbols-outlined text-lg">settings</span>
            </button>
            <button onClick={() => setIsAuthenticated(false)} className="text-sm font-bold text-gray-400">Salir</button>
        </div>
      </header>

      {/* Config Panel */}
      {showConfig && (
        <div className="bg-white border-b border-gray-200 p-4 animate-[slideDown_0.3s_ease-out]">
            <h3 className="font-extrabold text-[#181611] mb-4 text-xs uppercase tracking-widest">Ajustes Globales</h3>

            <div className="space-y-4 mb-6">
                <div>
                    <label className="text-xs font-bold text-gray-600 block mb-1">Tu URL Pública (Para el QR)</label>
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={publicUrl}
                            onChange={(e) => setPublicUrl(e.target.value)}
                            placeholder="https://mi-tienda.com"
                            className="flex-1 text-sm rounded-lg border-gray-200 focus:border-primary"
                        />
                        <button onClick={handleSavePublicUrl} className="bg-black text-white px-3 py-1 rounded-lg text-[10px] font-bold">Guardar URL</button>
                    </div>
                </div>

                <div className="border-t border-gray-100 pt-4">
                    <label className="text-xs font-bold text-gray-600 block mb-1">Cambiar PIN Admin</label>
                    <div className="flex gap-2">
                        <input 
                            type="password" 
                            value={newPin}
                            onChange={(e) => setNewPin(e.target.value)}
                            className="flex-1 text-sm rounded-lg border-gray-200 focus:border-primary"
                        />
                        <button onClick={handleChangePin} className="bg-black text-white px-3 py-1 rounded-lg text-[10px] font-bold">Cambiar</button>
                    </div>
                </div>

                <div className="border-t border-gray-100 pt-4">
                  <label className="text-xs font-bold text-gray-600 block mb-1">Configuración Supabase</label>
                  <div className="space-y-2">
                    <input 
                      type="text" 
                      value={sbUrl}
                      onChange={(e) => setSbUrl(e.target.value)}
                      placeholder="Supabase URL"
                      className="w-full text-sm rounded-lg border-gray-200 focus:border-primary"
                    />
                    <input 
