                      className="w-full text-sm rounded-lg border-gray-200 focus:border-primary"
                    />
                    <button onClick={handleSaveConfig} className="w-full bg-black text-white py-2 rounded-lg text-xs font-bold">Actualizar BD</button>
                  </div>
