import React, { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useOrders, useProducts } from '../App';
import { BRAND_CONFIG } from '../constants';

const AdminDashboardScreen: React.FC = () => {
  const navigate = useNavigate();
  const { orders, clearOrders, loading: ordersLoading } = useOrders();
  const { products } = useProducts();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [pin, setPin] = useState('');
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showQRModal, setShowQRModal] = useState(false);

  // QR Logic - Apunta automáticamente a la URL actual
  const currentAppUrl = window.location.origin + window.location.pathname;
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(currentAppUrl)}&color=000000&bgcolor=FFFFFF&margin=2`;

  const analytics = useMemo(() => {
    const totalSales = orders.reduce((acc, order) => acc + order.total, 0);
    const totalOrders = orders.length;

    const productCounts: { [key: string]: number } = {};
    orders.forEach(order => {
        if (Array.isArray(order.items)) {
            order.items.forEach(item => {
                const pId = item.productId || item.id;
                productCounts[pId] = (productCounts[pId] || 0) + item.quantity;
            });
        }
    });

    const topProducts = Object.entries(productCounts)
        .map(([id, count]) => {
            const product = products.find(p => p.id === id);
            return product ? { ...product, count } : null;
        })
        .filter(p => p !== null)
        .sort((a, b) => b!.count - a!.count)
        .slice(0, 3);

    return { totalSales, totalOrders, topProducts };
  }, [orders, products]);

  const handleLogin = (val: string) => {
     const storedPin = localStorage.getItem('potato_admin_pin') || '2024';
     if (val === storedPin) {
         setIsAuthenticated(true);
     } else {
         alert('PIN Incorrecto');
         setPin('');
     }
  };

  if (!isAuthenticated) {
      return (
          <div className="flex flex-col items-center justify-center min-h-screen bg-background-dark p-6 text-white">
              <span className="material-symbols-outlined text-6xl text-primary mb-4">lock</span>
              <h1 className="text-2xl font-bold mb-2">Acceso Privado</h1>
              <p className="text-gray-400 mb-8 text-center">Solo personal autorizado</p>
              <div className="w-full max-w-xs">
                  <input 
                    type="password" 
                    value={pin}
                    onChange={(e) => setPin(e.target.value)}
                    placeholder="PIN"
                    className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-center text-xl tracking-widest mb-4"
                    maxLength={10}
                  />
                  <button onClick={() => handleLogin(pin)} className="w-full bg-primary text-black font-bold py-4 rounded-xl">Entrar</button>
                  <button onClick={() => navigate('/')} className="w-full mt-4 text-gray-400 text-sm">Volver al Menú</button>
              </div>
          </div>
      );
  }

  return (
    <div className="flex min-h-screen flex-col bg-gray-50">
      <header className="flex items-center p-4 bg-white shadow-sm sticky top-0 z-20">
        <img src={BRAND_CONFIG.LOGO_URL} alt="Logo" className="h-10 w-10 object-contain mr-3" />
        <h2 className="text-lg font-bold flex-1">Admin Dashboard</h2>
        <button onClick={() => setIsAuthenticated(false)} className="text-sm font-bold text-gray-400">Salir</button>
      </header>

      <main className="p-4 space-y-6 flex-1">
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
            <p className="text-gray-500 text-[10px] font-bold uppercase tracking-wider">Ventas Totales</p>
            <p className="text-xl font-black text-primary">${analytics.totalSales.toLocaleString()}</p>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
            <p className="text-gray-500 text-[10px] font-bold uppercase tracking-wider">Pedidos</p>
            <p className="text-xl font-black text-black">{analytics.totalOrders}</p>
          </div>
        </div>

        <section className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="font-bold text-sm mb-4 uppercase tracking-widest">Lo más pedido</h3>
            <div className="space-y-4">
                {analytics.topProducts.map((p: any, i) => (
                    <div key={p.id} className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <span className="text-xs text-gray-400 font-bold">#{i+1}</span>
                            <p className="text-sm font-semibold">{p.name}</p>
                        </div>
                        <span className="bg-primary/10 text-primary px-2 py-0.5 rounded text-[10px] font-bold">{p.count}</span>
                    </div>
                ))}
            </div>
        </section>

        <section className="space-y-4">
            <div className="flex justify-between items-center">
                <h3 className="font-bold text-sm uppercase tracking-widest">Últimos Pedidos</h3>
                <button onClick={() => setShowDeleteModal(true)} className="text-red-500 text-xs font-bold">Limpiar</button>
            </div>
            {ordersLoading ? (
                <div className="flex justify-center py-10"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div></div>
            ) : orders.length === 0 ? (
                <p className="text-center text-gray-400 text-sm py-10">Sin historial</p>
            ) : (
                <div className="space-y-3 pb-24">
                    {orders.slice(0, 20).map(order => (
                        <div key={order.id} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex justify-between items-center">
                            <div>
                                <p className="font-bold text-sm">{order.customerName}</p>
                                <p className="text-[10px] text-gray-400">{order.date}</p>
                            </div>
                            <p className="font-bold text-primary">${order.total.toLocaleString()}</p>
                        </div>
                    ))}
                </div>
            )}
        </section>
      </main>

      <button onClick={() => setShowQRModal(true)} className="fixed bottom-6 right-6 size-14 bg-black text-white rounded-full shadow-2xl flex items-center justify-center z-50">
        <span className="material-symbols-outlined">qr_code_2</span>
      </button>

      {showQRModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6" onClick={() => setShowQRModal(false)}>
           <div className="bg-white rounded-[2rem] p-8 w-full max-w-sm flex flex-col items-center" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-bold mb-4">QR de tu Menú</h3>
              <div className="bg-gray-50 p-4 rounded-2xl mb-6">
                 <img src={qrCodeUrl} alt="QR" className="w-full aspect-square" />
              </div>
              <p className="text-xs text-gray-400 text-center mb-6">{currentAppUrl}</p>
              <button onClick={() => setShowQRModal(false)} className="w-full bg-black text-white font-bold py-3 rounded-xl">Cerrar</button>
           </div>
        </div>
      )}

      {showDeleteModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[110] flex items-center justify-center p-6">
           <div className="bg-white rounded-2xl p-6 w-full max-w-sm">
              <h3 className="text-lg font-bold mb-6">¿Borrar historial de pedidos?</h3>
              <div className="flex gap-3">
                  <button onClick={() => setShowDeleteModal(false)} className="flex-1 bg-gray-100 py-3 rounded-xl font-bold">No</button>
                  <button onClick={() => { clearOrders(); setShowDeleteModal(false); }} className="flex-1 bg-red-600 text-white py-3 rounded-xl font-bold">Sí, borrar</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboardScreen;
